using var adapter = new LabScriptedAdapter();
using var controller = new LabController(adapter);
string id = controller.Submit("SetLevel", 60, "D1");
Console.WriteLine(adapter.Sent.Count); // 1
Console.WriteLine(controller.Results[id]); // Pending
adapter.Emit(new LabCompletion(id, controller.Session, "Completed"));
Console.WriteLine(controller.Results[id]); // Completed
Console.WriteLine(controller.Applied); // 1

using var a = new LabScriptedAdapter();
using var b = new LabScriptedAdapter();
using var wrong = new LabController(b);
a.Send(new LabCommand("R7", 1, "QueryState", "D1", 0));
a.Emit(new LabCompletion("R7", 1, "Completed"));
Console.WriteLine(wrong.Applied); // 0
using var right = new LabController(a);
string id = right.Submit("QueryState", 0);
a.Emit(new LabCompletion(id, right.Session, "Completed"));
Console.WriteLine(right.Results[id]); // Completed
